/// 文本模式的「下一步」段。写操作的文本都以它收尾。
pub(crate) fn next_lines(head: String, resp: &Response, work: &WorkId) -> String {
    let mut text = head;
    if resp.next.is_empty() {
        text.push_str("没有下一步（Work 已结束）。\n");
        return text;
    }
    text.push_str("下一步：\n");
    for op in &resp.next {
        text.push_str(&format!("- {}\n", op.to_command_line(work)));
    }
    text
}

