/// `--summary` 与 `--reason` 经 `cli::parse_text_arg`；`--attempt` 经 `AttemptId::parse`。
/// `begin` 已随 T18 一并实现（`work cancel` 的测试要走它验证 `WORK_TERMINAL`，见 plan.md T18 任务卡）；
/// `submit` 与 `fail` 归 T19。
pub fn run(ctx: &Ctx, cmd: AttemptCmd) -> Outcome {
    match cmd {
