    for (i, row) in rows.iter().enumerate() {
        // rows 按 (id, version) 升序，同 id 的最后一行就是最高版本。
        let latest = rows.get(i + 1).is_none_or(|next| next.id != row.id);
        data.push(json!({
            "id": row.id,
            "version": row.version,
            "digest": row.digest,
            "latest": latest,
            "pending_publish": row.pending_publish,
        }));
        text.push_str(&format!(
            "{}  {}  {}{}\n",
            row.id,
            row.version,
            if latest { "latest" } else { "" },
            if row.pending_publish {
                "  待发布"
            } else {
                ""
            },
        ));
    }
    output::ok(text, None, None, data, Vec::new())
}

/// `workbook show <id>[@<version>]`：manifest、宿主资源声明与每个 Flow 的节点、边。
fn show(ctx: &Ctx, spec: &str) -> Outcome {
    let (id, version) = match parse_workbook_spec(spec) {
        Ok(v) => v,
        Err(m) => return output::param_error(m),
    };
    let repo = WorkbookRepo::new(ctx.home.clone());
    let loaded = match repo.load(&id, version.as_deref()) {
        Ok(l) => l,
        Err(e) => return crate::error_map::to_outcome(&e),
    };
    let mut flows = Vec::with_capacity(loaded.flows.len());
    let mut text = format!(
        "workbook: {}@{}（{}）\ndigest: {}\nrequires: {}\n",
        loaded.manifest.id(),
        loaded.manifest.version(),
        loaded.manifest.name(),
        loaded.digest.as_str(),
        if loaded.manifest.requires().is_empty() {
            "无".to_string()
        } else {
            loaded
                .manifest
                .requires()
                .iter()
                .map(|r| format!("{}:{}", r.kind().as_str(), r.name()))
                .collect::<Vec<_>>()
                .join(", ")
        },
    );
    if loaded.pending_publish {
        text.push_str("发布状态：待完成（正在读取已提交的冻结副本）\n");
    }
    for (def, graph) in &loaded.flows {
        // 有序起始输入键（GF-30）：与 runtime preflight 同一份 start_requirements，
        // 协调者第一次调用就能拿全开一个 Work 需要的键，不用失败 start 探测。
        let start_inputs = sheltie_core::work::start_requirements(graph);
        flows.push(json!({
            "id": def.id().as_str(),
            "entry": def.entry().as_str(),
            "start_inputs": start_inputs,
            "nodes": def.nodes().iter().map(|n| json!({
                "id": n.id().as_str(),
                "title": n.title(),
                "executor": n.executor().as_str(),
                "gate": n.gate(),
            })).collect::<Vec<_>>(),
            "edges": def.edges().iter().map(|e| json!({
                "from": e.from().as_str(),
                "to": e.to().as_str(),
                "kind": e.kind().as_str(),
            })).collect::<Vec<_>>(),
        }));
        text.push_str(&format!("\nflow {}（入口 {}）\n", def.id(), def.entry()));
        text.push_str(&format!(
            "  起始输入: {}\n",
            if start_inputs.is_empty() {
                "无".to_string()
            } else {
                start_inputs.join(", ")
            }
        ));
        for n in def.nodes() {
            text.push_str(&format!(
                "  {}  {}  {}{}\n",
                n.id(),
                n.title(),
                n.executor().as_str(),
                if n.gate() { "  [gate]" } else { "" }
            ));
        }
        for e in def.edges() {
            text.push_str(&format!(
                "  {} -> {}（{}）\n",
                e.from(),
                e.to(),
                e.kind().as_str()
            ));
        }
    }
    let data = json!({
        "id": loaded.manifest.id().as_str(),
        "version": loaded.manifest.version(),
        "name": loaded.manifest.name(),
        "description": loaded.manifest.description(),
        "digest": loaded.digest.as_str(),
        "pending_publish": loaded.pending_publish,
        "requires": loaded.manifest.requires(),
        "flows": flows,
    });
    output::ok(text, None, None, data, Vec::new())
}

/// `workbook remove <id>@<version>`。版本必须给全，防误删。
fn remove(ctx: &Ctx, spec: &str) -> Outcome {
    let (id, version) = match parse_workbook_spec(spec) {
        Ok(v) => v,
        Err(m) => return output::param_error(m),
    };
    let Some(version) = version else {
        return output::param_error(format!(
            "remove 必须给全版本，写 {id}@<version>；不接受「最高版本」默认"
        ));
    };
    let repo = WorkbookRepo::new(ctx.home.clone());
    match repo.remove(&id, &version, ctx.request_id.clone()) {
        Ok(snapshot) => {
            let data = output::replayed_data(snapshot.data, snapshot.replayed);
            let text = format!("已删除 {id}@{version}\n");
            output::ok(text, Some(snapshot.request_id), None, data, Vec::new())
        }
        Err(e) => crate::error_map::to_outcome(&e),
    }
}

/// `workbook verify [<id>@<version>]`。省略参数核对全部。任一非 `ok` 则 `WORKBOOK_TAMPERED`。
fn verify(ctx: &Ctx, spec: Option<&str>) -> Outcome {
    let filter = match spec {
        None => None,
        Some(s) => match parse_workbook_spec(s) {
            Ok((id, Some(version))) => Some((id, version)),
            Ok((_, None)) => {
                return output::param_error(format!(
                    "verify 要么不带参数核对全部，要么写全 {s}@<version>"
                ));
            }
            Err(m) => return output::param_error(m),
        },
    };
    let repo = WorkbookRepo::new(ctx.home.clone());
    let rows = match repo.verify(filter.as_ref().map(|(i, v)| (i.as_str(), v.as_str()))) {
        Ok(r) => r,
        Err(e) => return crate::error_map::to_outcome(&e),
    };
    let mut text = String::new();
    for row in &rows {
        text.push_str(&format!(
            "{}@{}  {}{}\n",
            row.id,
            row.version,
            match row.status {
                sheltie_runtime::VerifyStatus::Ok => "ok",
                sheltie_runtime::VerifyStatus::Tampered => "tampered",
                sheltie_runtime::VerifyStatus::Missing => "missing",
            },
            if row.pending_publish {
                "  待发布"
            } else {
                ""
            },
        ));
    }
    let all_ok = rows
        .iter()
        .all(|r| r.status == sheltie_runtime::VerifyStatus::Ok);
    if all_ok {
        output::ok(text, None, None, json!({ "results": rows }), Vec::new())
    } else {
        let mut out = crate::output::err(
            sheltie_core::ErrorCode::WorkbookTampered,
            "已装 Workbook 与记录不符".to_string(),
            Some(json!({ "results": rows })),
            Vec::new(),
        );
        out.text = text;
        out
    }
}
//! 输出：给人读的文本，或协议 §5 的 JSON 响应封装。

use serde::Serialize;
use sheltie_core::ErrorCode;
use sheltie_core::ids::WorkId;
use sheltie_core::work::NextOp;
use sheltie_runtime::Response;

/// 成功响应封装。
#[derive(Debug, Serialize)]
pub struct OkEnvelope<T: Serialize> {
    pub ok: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub request_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub revision: Option<u64>,
    pub data: T,
    pub next: Vec<NextOp>,
}

/// 一次命令的输出，由命令模块构造，`dispatch` 决定怎么打印。
#[derive(Debug)]
pub struct Outcome {
    /// 文本模式下打印的内容。
    pub text: String,
    /// JSON 模式下的完整响应封装。
    pub json: serde_json::Value,
    pub exit_code: i32,
}

/// 把成功结果包成两种形式。`text` 由调用方渲染。`next` 为空的命令用一个；
/// Work 写操作用 [`ok_response`]，只读操作用 [`ok_work_next`]。
pub fn ok<T: Serialize>(
    text: String,
    request_id: Option<String>,
    revision: Option<u64>,
    data: T,
    next: Vec<NextOp>,
) -> Outcome {
    let json = to_value_lossy(OkEnvelope {
        ok: true,
        request_id,
        revision,
        data,
        next,
    });
    Outcome {
        text,
        json,
        exit_code: 0,
    }
}

/// Work 写操作只渲染提交时快照；`next` 与只读状态卡使用同一协议形状。
pub(crate) fn ok_response(text: String, response: Response, work: &WorkId) -> Outcome {
    let next = response
        .next
        .iter()
        .map(|op| sheltie_core::work::render::next_item_json(work, op))
        .collect();
    ok_work_next(
        text,
        Some(response.request_id),
        Some(response.revision),
        replayed_data(response.data, response.replayed),
        next,
    )
}

pub(crate) fn replayed_data(mut data: serde_json::Value, replayed: bool) -> serde_json::Value {
    if let Some(map) = data.as_object_mut() {
        map.insert("replayed".to_string(), serde_json::Value::Bool(replayed));
    }
    data
}

/// `next` 已是协议 §5 形状（core `next_item_json` 生成），
/// 与状态卡 `data.next` 完全同形（O13），不再重复组装。
pub(crate) fn ok_work_next(
    text: String,
    request_id: Option<String>,
    revision: Option<u64>,
    data: serde_json::Value,
    next: Vec<serde_json::Value>,
) -> Outcome {
    let mut root = serde_json::Map::new();
    root.insert("ok".to_string(), serde_json::Value::Bool(true));
    if let Some(id) = request_id {
        root.insert("request_id".to_string(), serde_json::json!(id));
    }
    if let Some(rev) = revision {
        root.insert("revision".to_string(), serde_json::json!(rev));
    }
    root.insert("data".to_string(), data);
    root.insert("next".to_string(), serde_json::Value::Array(next));
    Outcome {
        text,
        json: serde_json::Value::Object(root),
        exit_code: 0,
    }
}

/// 把错误包成两种形式。退出码 1。
pub fn err(
    code: ErrorCode,
    message: String,
    detail: Option<serde_json::Value>,
    next: Vec<NextOp>,
) -> Outcome {
    let mut error = serde_json::Map::new();
    error.insert("code".to_string(), to_value_lossy(code));
    error.insert("message".to_string(), serde_json::json!(message));
    if let Some(d) = detail {
        error.insert("detail".to_string(), d);
    }
    let json = serde_json::json!({
        "ok": false,
        "error": serde_json::Value::Object(error),
        "next": to_value_lossy(next),
    });
    Outcome {
        text: format!("{message}\n"),
        json,
        exit_code: 1,
    }
}

/// 参数格式错误的统一出口：`INVALID_REQUEST` 封装、退出码 2（协议 §5「参数解析错误 2」）。
pub(crate) fn param_error(message: String) -> Outcome {
    let mut out = err(ErrorCode::InvalidRequest, message, None, Vec::new());
    out.exit_code = 2;
    out
}

/// 打印。JSON 模式打一行 `json`；文本模式打 `text`。错误走 stderr。
pub fn print(outcome: &Outcome, json_mode: bool) {
    if json_mode {
        println!("{}", outcome.json);
    } else if outcome.exit_code == 0 {
        print!("{}", outcome.text);
    } else {
        eprint!("{}", outcome.text);
    }
}

pub(crate) fn raw_error(error: &sheltie_runtime::Error) -> i32 {
    let outcome = crate::error_map::to_outcome(error);
    eprint!("{}", outcome.text);
    outcome.exit_code
}

pub(crate) fn raw_param_error(message: &str) -> i32 {
    eprintln!("{message}");
    2
}

/// 这些响应类型全是普通数据，序列化实际不会失败；真失败了给 `null` 也不比 panic 差。
fn to_value_lossy<T: Serialize>(value: T) -> serde_json::Value {
    serde_json::to_value(value).unwrap_or(serde_json::Value::Null)
}
